import json,numpy as np
from PIL import Image
S=json.load(open('/app/output/spec.json'))
C=S['cameras']['egocentric_mirrored_camera']; K=np.array(C['intrinsic_cv']); E=np.array(C['extrinsic_cv']); R=E[:,:3]; t=E[:,3]
I=np.load('/app/runs/initial/last_depth_egocentric_mirrored_camera.npy'); im=np.asarray(Image.open('/app/runs/initial/last/egocentric_mirrored_camera.jpg'))
def world(u,v):
 z=float(I[v,u]); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]); return np.linalg.inv(R)@(p-t)
for p in [(380,145),(385,150),(385,165),(385,180),(520,150),(520,165),(520,180),(520,200),(400,250),(500,250),(600,250),(500,300),(500,400)]:
 print(p,'d',round(float(I[p[1],p[0]]),3),'xyz',np.round(world(*p),3))
# cube pixels saturated-ish/depth object clusters in box and bowl mask
for box,name in [((330,90,440,200),'cube'),((465,110,590,220),'bowl')]:
 x0,y0,x1,y1=box
 yy,xx=np.mgrid[y0:y1,x0:x1]; pix=im[y0:y1,x0:x1]; dep=I[y0:y1,x0:x1]
 if name=='cube': m=(dep>0)&((pix[:,:,2]>pix[:,:,0]*1.35)|(pix[:,:,1]>pix[:,:,0]*1.3)|(pix[:,:,0]>pix[:,:,1]*1.35))
 else: m=(dep>0)&(pix[:,:,0]>pix[:,:,1]*1.35)&(pix[:,:,0]>pix[:,:,2]*1.35)
 inds=np.argwhere(m); w=np.array([world(int(xx0),int(yy0)) for yy0,xx0 in inds]);
 print(name,'count',len(inds),'pix centroid',inds.mean(0)+[y0,x0],'world median',np.median(w,0),'world mean',w.mean(0),'zrange',np.percentile(w[:,2],[10,50,90]))
