python - <<'PY'
import json,numpy as np
from PIL import Image
M=json.load(open('/app/runs/initial/meta.json'))['cameras']['egocentric_mirrored_camera']; K=np.array(M['intrinsic_cv']); E=np.array(M['extrinsic_cv']); R=E[:,:3]; t=E[:,3]
I=np.load('/app/runs/initial/last_depth_egocentric_mirrored_camera.npy'); im=np.asarray(Image.open('/app/runs/initial/last/egocentric_mirrored_camera.jpg')).astype(float)
def world(u,v,z=None):
 z=float(I[v,u] if z is None else z); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]); return np.linalg.inv(R)@(p-t)
for box,name in [((350,100,420,200),'cube'),((460,110,590,220),'bowl')]:
 x0,y0,x1,y1=box; pix=im[y0:y1,x0:x1]; dep=I[y0:y1,x0:x1]; mx=pix.max(2); mn=pix.min(2)
 if name=='cube': m=(dep>0)&((mx-mn)>55)&(mx>100)
 else: m=(dep>0)&(pix[:,:,0]>pix[:,:,1]*1.45)&(pix[:,:,0]>pix[:,:,2]*1.35)&(pix[:,:,0]>35)
 inds=np.argwhere(m); pts=np.array([world(int(x0+x),int(y0+y)) for y,x in inds]);
 print('\n',name,'count',len(inds),'px bbox',inds.min(0)+[y0,x0],inds.max(0)+[y0,x0], 'centroid',inds.mean(0)+[y0,x0])
 for axis in range(3): print(' xyz',axis, np.percentile(pts[:,axis],[5,25,50,75,95]).round(3))
 print('mean',pts.mean(0).round(3),'median',np.median(pts,0).round(3))
# world coords select points on cube top face approx pixels by color, and table point directly behind
for p in [(377,130),(385,135),(390,145),(375,165),(390,180),(407,180),(380,190),(400,195),(520,130),(520,150),(500,180),(545,180),(520,210)]: print(p, im[p[1],p[0]].astype(int), round(float(I[p[1],p[0]]),3), world(*p).round(3))
